head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil35708";
scwin.data = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil35708.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.init();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil35708.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    scwin.data = ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : scwin.openerScwin()).dataArr_trust);
    if (!Array.isArray(scwin.data)) { /* TODO Stage2: [sdd] 인쇄 데이터 부재(호스트 진입 필요) — jldfil35708 */ return; }
    const gubun = scwin.data[11].calc_gubun;
    if (gubun === "1") {
        $c.util.getComponent("ipt_calcGubun").setValue("ETF");
        $c.util.getComponent('txt_tdNm4').setLabel("* 상장할 신탁원본액");
    } else {
        if (gubun === "2") {
            $c.util.getComponent("ipt_calcGubun").setValue("ETN");
            $c.util.getComponent('txt_tdNm4').setLabel("* 발행원본액");
        } else {
            if (gubun === "3") {
                $c.util.getComponent("ipt_calcGubun").setValue("ELW");
                $c.util.getComponent('txt_tdNm4').setLabel("* 발행총액");
            } else {
                if (gubun === "4") {
                    $c.util.getComponent("ipt_calcGubun").setValue("상장형 수익증권");
                    $c.util.getComponent('txt_tdNm4').setLabel("* 상장할 신탁원본액");
                }
            }
        }
    }
    $c.util.getComponent("ipt_issueCode1").setValue(scwin.data[0].issueCode);
    $c.util.getComponent("ipt_issueCode2").setValue(scwin.data[1].issueCode);
    $c.util.getComponent("ipt_issueCode3").setValue(scwin.data[2].issueCode);
    $c.util.getComponent("ipt_issueCode4").setValue(scwin.data[3].issueCode);
    $c.util.getComponent("ipt_issueCode5").setValue(scwin.data[4].issueCode);
    $c.util.getComponent("ipt_issueCode6").setValue(scwin.data[5].issueCode);
    $c.util.getComponent("ipt_issueCode7").setValue(scwin.data[6].issueCode);
    $c.util.getComponent("ipt_issueCode8").setValue(scwin.data[7].issueCode);
    $c.util.getComponent("ipt_issueCode9").setValue(scwin.data[8].issueCode);
    $c.util.getComponent("ipt_issueCode10").setValue(scwin.data[9].issueCode);
    $c.util.getComponent("ipt_commission1").setValue(scwin.data[0].trust_comm);
    await scwin.numFormat($c.util.getComponent('ipt_commission1'));
    $c.util.getComponent("ipt_commission2").setValue(scwin.data[1].trust_comm);
    await scwin.numFormat($c.util.getComponent('ipt_commission2'));
    $c.util.getComponent("ipt_commission3").setValue(scwin.data[2].trust_comm);
    await scwin.numFormat($c.util.getComponent('ipt_commission3'));
    $c.util.getComponent("ipt_commission4").setValue(scwin.data[3].trust_comm);
    await scwin.numFormat($c.util.getComponent('ipt_commission4'));
    $c.util.getComponent("ipt_commission5").setValue(scwin.data[4].trust_comm);
    await scwin.numFormat($c.util.getComponent('ipt_commission5'));
    $c.util.getComponent("ipt_commission6").setValue(scwin.data[5].trust_comm);
    await scwin.numFormat($c.util.getComponent('ipt_commission6'));
    $c.util.getComponent("ipt_commission7").setValue(scwin.data[6].trust_comm);
    await scwin.numFormat($c.util.getComponent('ipt_commission7'));
    $c.util.getComponent("ipt_commission8").setValue(scwin.data[7].trust_comm);
    await scwin.numFormat($c.util.getComponent('ipt_commission8'));
    $c.util.getComponent("ipt_commission9").setValue(scwin.data[8].trust_comm);
    await scwin.numFormat($c.util.getComponent('ipt_commission9'));
    $c.util.getComponent("ipt_commission10").setValue(scwin.data[9].trust_comm);
    await scwin.numFormat($c.util.getComponent('ipt_commission10'));
    $c.util.getComponent("ipt_trustCount1").setValue(scwin.data[0].trust_count);
    $c.util.getComponent("ipt_trustCount2").setValue(scwin.data[1].trust_count);
    $c.util.getComponent("ipt_trustCount3").setValue(scwin.data[2].trust_count);
    $c.util.getComponent("ipt_trustCount4").setValue(scwin.data[3].trust_count);
    $c.util.getComponent("ipt_trustCount5").setValue(scwin.data[4].trust_count);
    $c.util.getComponent("ipt_trustCount6").setValue(scwin.data[5].trust_count);
    $c.util.getComponent("ipt_trustCount7").setValue(scwin.data[6].trust_count);
    $c.util.getComponent("ipt_trustCount8").setValue(scwin.data[7].trust_count);
    $c.util.getComponent("ipt_trustCount9").setValue(scwin.data[8].trust_count);
    $c.util.getComponent("ipt_trustCount10").setValue(scwin.data[9].trust_count);
    $c.util.getComponent("ipt_totListAmtTrust").setValue(scwin.data[10].tot_list_amt_trust);
    $c.util.getComponent("ipt_listCommSumTrust").setValue(scwin.data[10].list_comm_sum_trust);
    await $c.win.print();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name unformat
 * @description unformat 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.unformat = function (obj) {
    let temp = "";
    const n = String(obj.value);
    const len = n.length;
    let pos = 0;
    let ch = '';
    while (pos < len) {
        ch = n.charAt(pos);
        if (((ch >= '0') && (ch <= '9')) || (ch === '-')) {
            temp = temp + ch;
        }
        pos = pos + 1;
    }
    obj.value = temp;
    return true;
};

/**
 * @method
 * @name numFormat
 * @description num Format 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.numFormat = async function (obj) {
    if ((obj.getValue() == null ? '' : String(obj.getValue())) !== '' && !scwin.isMinusNum(obj.getValue())) {
        obj.setValue("");
        await $c.win.alert("숫자만 입력가능합니다.");
        (obj && obj.setFocus ? obj.setFocus() : (obj && obj.focus ? obj.focus() : void 0));
        return;
    }
    scwin.unformat(obj);
    if ((obj.getValue() == null ? '' : String(obj.getValue())) === '') {
        return;
    }
    if (isNaN(obj.getValue())) {
        obj.setValue("");
        return;
    }
    let str = Number(obj.getValue()) + "";
    let sMinusChar = "";
    if (Number(obj.getValue()) < 0) {
        str = str.substring(1);
        sMinusChar = "-";
    }
    const leng = str.length;
    const size = 3;
    const cnt = Math.floor(leng / size);
    const pos = leng % size;
    let result = "";
    if (cnt === 0) {
        obj.setValue(Number(obj.getValue()));
        return;
    }
    for (let i = cnt; i > 0; i = i - 1) {
        result = "," + str.substr(pos + (i - 1) * size, size) + result;
    }
    if (result !== '') {
        if (pos === 0) {
            obj.setValue(sMinusChar + result.substring(1));
        } else {
            obj.setValue(sMinusChar + str.substr(0, pos) + result);
        }
    }
    return;
};

/**
 * @method
 * @name isMinusNum
 * @description is Minus Num 처리
 * @param {*} name name
 * @returns {void}
 * @hidden N
 */
scwin.isMinusNum = function (name) {
    let ch = "\0";
    let flag = true;
    ch = name.charAt(0);
    flag = ((ch >= '0' && ch <= '9') || ch === '-') ? true : false;
    for (let i = 1, ch = name.charAt(i); (i < name.length) && (flag); ch = name.charAt(++i)) {
        if ((ch >= '0') && (ch <= '9')) {

        } else {
            flag = false;
        }
    }
    return flag;
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
